//! What UseDefs=0 changes in a SpecFrame, DSBSpecFrame and TimeFrame,
//! checked against the C library.
//!
//! `spec_use_defs_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/spec_use_defs_probe.c`. A conversion that needs an
//! attribute which has not been set is refused with AST__NOVAL: the StdOfRest
//! of both SpecFrames, a RestFreq for a velocity system, the RefRA, RefDec,
//! observer position or Epoch for a change of rest frame (specframe.c
//! `MakeSpecMapping`, `SorConvert`, `VerifyAttrs`), the IF and Dsbcenter for
//! a change of sideband (dsbspecframe.c `GetLO`), and the TimeScale and
//! StdOfRest when picking axes (timeframe.c, specframe.c `SubFrame`). A
//! SpecFrame Title leaves out a RestFreq that has not been set.

#[path = "spec_use_defs_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::error::ErrorCode;
use starlink_ast::frames::FrameSearch;
use starlink_ast::frames::{
    DSBSpecFrame, DynFrame, Frame, FrameRef, SideBand, SpecFrame, SpecSystem, StdOfRest, TimeFrame,
    TimeScale, TimeSystem, pick_axes,
};

/// The radians of a sexagesimal angle, in hours or degrees.
fn sexagesimal(v: &str, hours: bool) -> f64 {
    let parts: Vec<f64> = v.split(':').map(|p| p.parse().unwrap()).collect();
    let deg = parts[0] + parts[1] / 60.0 + parts[2] / 3600.0;
    (if hours { deg * 15.0 } else { deg }).to_radians()
}

fn apply_spec(f: &mut SpecFrame, key: &str, value: &str) {
    match key {
        "System" => f.set_system(SpecSystem::parse(value).unwrap()).unwrap(),
        "StdOfRest" => f.set_std_of_rest(StdOfRest::parse(value).unwrap()).unwrap(),
        "UseDefs" => f.set_use_defs(value == "1").unwrap(),
        "RestFreq" => f.set_rest_freq(value.parse::<f64>().unwrap() * 1e9),
        "RefRA" => f.set_ref_ra(sexagesimal(value, true)),
        "RefDec" => f.set_ref_dec(sexagesimal(value, false)),
        "ObsLon" => Frame::set_obs_lon(f, value.parse::<f64>().unwrap().to_radians()).unwrap(),
        "ObsLat" => Frame::set_obs_lat(f, value.parse::<f64>().unwrap().to_radians()).unwrap(),
        "ObsAlt" => Frame::set_obs_alt(f, value.parse().unwrap()).unwrap(),
        "Epoch" => f.set_epoch_year(value.parse().unwrap()),
        "SourceVel" => f.set_source_vel_cur(value.parse().unwrap()),
        "SourceVRF" => f.set_source_vrf(StdOfRest::parse(value).unwrap()).unwrap(),
        other => panic!("no Rust set-up for {other}"),
    }
}

fn make(class: &str, settings: &str) -> DynFrame {
    let pairs = settings
        .split(',')
        .filter(|s| !s.is_empty())
        .map(|s| s.split_once('=').unwrap());
    match class {
        "SpecFrame" => {
            let mut f = SpecFrame::unset_system();
            pairs.for_each(|(k, v)| apply_spec(&mut f, k, v));
            Box::new(f)
        }
        "DSBSpecFrame" => {
            let mut f = DSBSpecFrame::unset_system();
            for (k, v) in pairs {
                match k {
                    "SideBand" => f.set_sideband(SideBand::parse(v).unwrap()),
                    "AlignSideBand" => f.set_align_sideband(v == "1"),
                    "IF" => f.set_if_ghz(v.parse().unwrap()),
                    "DSBCentre" => f.set_dsb_centre_cur(v.parse().unwrap()).unwrap(),
                    _ => apply_spec(f.spec_mut(), k, v),
                }
            }
            Box::new(f)
        }
        "TimeFrame" => {
            let mut f = TimeFrame::unset_system();
            for (k, v) in pairs {
                match k {
                    "System" => f.set_system(TimeSystem::parse(v).unwrap()).unwrap(),
                    "TimeScale" => f.set_timescale(TimeScale::parse(v).unwrap()).unwrap(),
                    "UseDefs" => f.set_use_defs(v == "1").unwrap(),
                    other => panic!("no Rust set-up for {other}"),
                }
            }
            Box::new(f)
        }
        other => panic!("no Rust set-up for {other}"),
    }
}

#[test]
fn titles_match_the_c_library() {
    for &(settings, want) in cases::TITLES {
        assert_eq!(
            make("SpecFrame", settings).title().unwrap(),
            want,
            "[{settings}]"
        );
    }
}

#[test]
fn conversions_match_the_c_library() {
    let mut failures = Vec::new();
    for &(class, target, template, want) in cases::CONVERSIONS {
        let mut t = make(class, target);
        let map = if template == "pick" {
            pick_axes(t.as_ref(), &[1]).map(|(_, map)| Some(map))
        } else {
            t.find_frame_template(make(class, template).as_ref(), "")
                .map(|fs| fs.map(|fs| fs.mapping(FrameRef::Base, FrameRef::Current).unwrap()))
        };
        let got = match map {
            Err(e) if e.code() == ErrorCode::Noval => Err("Noval"),
            Err(e) => panic!("{class} [{target}] -> [{template}]: {e}"),
            Ok(None) => Ok(None),
            Ok(Some(map)) => {
                let out = map
                    .transform(&PointSet::from_rows([[230.0]]), true)
                    .unwrap();
                Ok(Some(out.point(0)[0]))
            }
        };
        if got != want {
            failures.push(format!(
                "{class} [{target}] -> [{template}]: got {got:?}, C gives {want:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
